ROOT = pathlib.Path(__file__).resolve().parents[1]
LF = ROOT / "level_factory"
PINS = {'apps/cli/commands/__init__.py': 'a6c3821e82733ab1'}
EDITS = {'apps/cli/commands/__init__.py': [('lines 1718-1719', '\ndef deal_signs(ws, buildings, theme: str) -> dict[str, str]:\n', '\n#: A BANK\'S NAME IS ZOO\'S (0.262.0). Zoo 1.138.0 names a bank on four more\n#: faces than its band -- the teller line\'s nameboard, the time-and-temperature\n#: sign, the drive-up canopy\'s fascia, the door -- every one by\n#: `storefront_names`\' rule: these four names, the crc32 of the business, which\n#: for a library shell is its archetype (Deli Counter\'s `bank_teller_variant`,\n#: Lot\'s `bank_sign_variant`, Zoo\'s `teller_line_forms.variant_for`). The deal\n#: keyed its own hash, so on the bank level (bank_block_001, seed 9082) the band\n#: said MATTRESS MONEY TRUST over a line, a sign and a canopy saying YOUSE\n#: CREDIT CO-OP. A bank\'s deal now starts at Zoo\'s name; the street\'s one-name\n#: rule still moves a second bank on to the next. Pixelcoat\'s delco profile\n#: lists the same four. `tests/unit/test_bank_deal.py` holds the list to Zoo.\nZOO_BANK_NAMES = ("FIRST DELCO SAVINGS", "PIKE SAVINGS & LOAN", "MATTRESS MONEY TRUST", "YOUSE CREDIT CO-OP")\n\n\ndef zoo_bank_name(key: str) -> str:\n    """The name Zoo\'s `storefront_names.sign_for` gives a bank whose business is ``key``."""\n    import zlib\n    return ZOO_BANK_NAMES[(zlib.crc32(str(key or "").encode("utf-8")) & 0xFFFFFFFF) % len(ZOO_BANK_NAMES)]\n\n\ndef deal_signs(ws, buildings, theme: str) -> dict[str, str]:\n'), ('lines 1758-1759', '        start = h % len(pool)\n        pick = None\n', '        start = h % len(pool)\n        # a bank starts at the name Zoo\'s other faces give it\n        if family == "bank":\n            want = zoo_bank_name(key)\n            start = next((i for i, s in enumerate(pool) if s.get("text") == want), start)\n        pick = None\n')]}
NEW_FILES = {'tests/unit/test_bank_deal.py': '"""A bank\'s band is dealt the name Zoo gives its other faces (0.262.0).\n\nZoo 1.138.0 names a bank on its teller line, its time-and-temperature sign, its drive-up canopy and its door, every\none by `storefront_names`\' rule, and the deal now starts there. FAILS ON 0.261.0: bank_branch_a02 was dealt MATTRESS\nMONEY TRUST under a line saying YOUSE CREDIT CO-OP (the bank level, seed 9082).\n"""\nimport importlib\nimport sys\n\nimport apps.cli.commands as cmds\nfrom tests.siblings import sibling_repo\nfrom tests.unit.test_signs_in_site_spec import _Workspace\n\nZOO = sibling_repo("zoo", marker="zoo_keeper/core/storefront_names.py")\n\n\ndef _slug_text(ws, slug):\n    return next(s["text"] for s in cmds._sign_profile(ws, "delco_1997") if s["slug"] == slug)\n\n\ndef test_a_library_bank_is_dealt_zoos_name():\n    ws = _Workspace()\n    for shell in ("bank_branch_a02", "bank_branch_a03", "bank_branch_a04", "bank_job", "bank_tower_a01",\n                  "credit_union_a01"):\n        deal = cmds.deal_signs(ws, [{"id": "b0", "archetype": shell}], "delco_1997")\n        assert _slug_text(ws, deal[shell]) == cmds.zoo_bank_name(shell), shell\n    # the bank level\'s bank, by name\n    deal = cmds.deal_signs(ws, [{"id": "b0", "archetype": "bank_branch_a02"}], "delco_1997")\n    assert _slug_text(ws, deal["bank_branch_a02"]) == "YOUSE CREDIT CO-OP"\n\n\ndef test_two_banks_with_one_name_on_a_street_still_get_two():\n    ws = _Workspace()\n    # find two library shells Zoo names alike\n    shells = ["bank_branch_a0%d" % i for i in range(1, 10)] + ["bank_job", "bank_tower_a01", "bank_tower_a02",\n                                                               "bank_tower_a03", "credit_union_a01"]\n    by_name = {}\n    for s in shells:\n        by_name.setdefault(cmds.zoo_bank_name(s), []).append(s)\n    pair = next(v[:2] for v in by_name.values() if len(v) >= 2)\n    deal = cmds.deal_signs(ws, [{"id": "b0", "archetype": pair[0]}, {"id": "b1", "archetype": pair[1]}], "delco_1997")\n    assert deal[pair[0]] != deal[pair[1]]\n    assert _slug_text(ws, deal[pair[0]]) == cmds.zoo_bank_name(pair[0])\n\n\ndef test_the_mirror_is_zoos_and_the_profiles():\n    ws = _Workspace()\n    banks = [s["text"] for s in cmds._sign_profile(ws, "delco_1997") if "bank" in (s.get("families") or [])]\n    assert sorted(banks) == sorted(cmds.ZOO_BANK_NAMES)\n    if ZOO is None:\n        import pytest\n        pytest.skip("no zoo checkout beside this repo")\n    if str(ZOO) not in sys.path:\n        sys.path.insert(0, str(ZOO))\n    SN = importlib.import_module("zoo_keeper.core.storefront_names")\n    names = next(n for kind, _m, n in SN.KINDS if kind == "bank")\n    assert tuple(names) == cmds.ZOO_BANK_NAMES\n    for shell in ("bank_branch_a02", "credit_union_a01", "bank_job"):\n        assert SN.sign_for(shell)["text"] == cmds.zoo_bank_name(shell), shell\n'}
CHANGELOG = "## [0.262.0] - a bank's band is dealt the name its other faces already give it\n\nFound by the first frames of the bank's outside (the factory's `docs/findings/bank_interior/`, frame 12, the bank level\non Zoo 1.138.0 and Lot 0.132.0). The storefront band said MATTRESS MONEY TRUST over a teller line, a time-and-temperature\nsign and a drive-up canopy that said YOUSE CREDIT CO-OP.\n\n### Changed\n- **A bank's deal starts at Zoo's name** (`deal_signs`, `zoo_bank_name`, `ZOO_BANK_NAMES`).\n  - Zoo 1.138.0 names a bank on four faces besides its band -- the teller line's nameboard, the time-and-temperature\n    sign, the canopy's fascia, the door -- every one by `storefront_names`' rule: its four bank names, by the crc32 of\n    the business, which for a library shell is its archetype. Deli Counter (`bank_teller_variant`) and Lot\n    (`bank_sign_variant`) mirror that rule; the deal keyed its own hash and disagreed.\n  - The deal is still the walker's option A (one business a shell, the band and the door one deal). The street's\n    one-name rule still moves a second bank sharing that name on to the next.\n  - Pixelcoat's `delco_1997` profile lists the same four bank names, so the name is always in the pool.\n  - Every other family is dealt as before.\n  - Not covered: a brief's own generated bank, whose deal reads its preset where Deli Counter keys its generated name;\n    it can still disagree.\n\n### Measured\n- The bank level's bank (`bank_branch_a02`) is dealt YOUSE CREDIT CO-OP, its line's, its sign's and its canopy's name.\n  It was dealt MATTRESS MONEY TRUST.\n\n### Tests\n- `tests/unit/test_bank_deal.py` (new; fails on 0.261.0, which has no `zoo_bank_name`):\n  - every library bank is dealt Zoo's name;\n  - two banks Zoo names alike on one street still get two;\n  - the mirror is Zoo's list and the profile's, and names each shell as Zoo's `sign_for` does, when Zoo is beside the\n    repo.\n\n"
OLD_VERSION, NEW_VERSION = '0.261.0', '0.262.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
